const AVAILABLE = new Set(CAST_ART)

/** URL of one cast image, or undefined while it has not been rendered. */
export const castArtUrl = (asset: string): string | undefined =>
  AVAILABLE.has(asset) ? `/emperor-of-dust/cast/${asset}.webp` : undefined

export type Mood = 'neutral' | 'happy' | 'excited' | 'sad' | 'angry'

/** An illustrated mood, falling back to the character's neutral illustration. */
export const illustration = (
  group: 'followers' | 'npcs',
  slug: string,
  mood: Mood = 'neutral',
): string | undefined =>
  castArtUrl(`${group}/${slug}/illustrated/${mood}`) ??
  castArtUrl(`${group}/${slug}/illustrated/neutral`)

/** A follower portrait, falling back to the neutral portrait, then the illustration. */
export const followerPortrait = (
  id: string,
  state: 'neutral' | 'injured' | 'dead' = 'neutral',
): string | undefined =>
  castArtUrl(`followers/${id}/portrait/${state}`) ??
  castArtUrl(`followers/${id}/portrait/neutral`) ??
  castArtUrl(`followers/${id}/illustrated/neutral`)
